query:
SELECT r.id, r.sponsorId, r.submittedAt, r.status, s.companyName 
FROM rankingsSubmissions r 
LEFT JOIN sponsors s ON r.sponsorId = s.id 
ORDER BY r.sponsorId;

SELECT id, companyName, contactEmail FROM sponsors ORDER BY id;

